 {q:"site:docs.entire.io analytics Entire CLI checkpoints push GitHub dashboard"},
 {q:"site:docs.entire.io \"Entire analytics\""},
 {q:"site:docs.entire.io Codex Entire agent add git refs checkpoints"}
],response_length:"long"}); text(r);

